// Кейс: .qa/tests/subscription/SUB-001.md · план: .qa/e2e-app/specs/app.md (1.16)
// РУЧНОЕ ПРЕДУСЛОВИЕ: приложение залогинено под user2 (пробный период закончился 14.10.2026) и запуск с BANCI_ACCOUNT=user2.
// Тест пароли не вводит и аккаунт не переключает. Без BANCI_ACCOUNT=user2 — пропуск. Ничего не меняет (только чтение).
import { by, assert, skip } from '../../lib/appium.mjs';
import { onHome, openTab } from '../../lib/banci.mjs';

export const name = '«מנוי» после конца пробного периода: «מנוי, הסתיים», «תקופת הניסיון הסתיימה ב-14 באוק׳ 2026», без «מסתיימת ב-»/«תקופת ניסיון» #a93d03 @iphone @app @prod-safe';

export default async function (app) {
  if (process.env.BANCI_ACCOUNT !== 'user2') {
    skip('нужен аккаунт user2 (пробный период закончился 14.10.2026): войти в приложение вручную под user2 и запустить с BANCI_ACCOUNT=user2');
  }

  // 1. «חשבון» → строка «מנוי, הסתיים».
  await onHome(app);
  await openTab(app, 'חשבון');
  const row = await app.scrollTo(by.begins('מנוי,'), { what: 'строка «מנוי, …» в «חשבון»' });
  const rowName = String(await row.attr('name'));
  assert(rowName === 'מנוי, הסתיים', `строка в «חשבון» — «מנוי, הסתיים» (сейчас «${rowName}»; «מנוי, תקופת ניסיון» — баг #a93d03 или вход не под user2)`);

  // 2. Тап → экран «מנוי».
  await row.click();
  await app.waitFor(by.contains('מנוי משפחתי'), { timeout: 20000, what: '«מנוי משפחתי» на экране «מנוי»' });

  // 3. Статус и тексты.
  const statusEnded = (await app.exists(by.exact('הסתיים'))) || (await app.exists(`(${by.contains('מנוי משפחתי')}) AND (name CONTAINS "הסתיים" OR label CONTAINS "הסתיים")`));
  assert(statusEnded, 'статус «הסתיים» рядом с «מנוי משפחתי»');
  await app.waitFor(by.contains('תקופת הניסיון הסתיימה ב-14 באוק'), { what: '«תקופת הניסיון הסתיימה ב-14 באוק׳ 2026»' });
  const date = String(await (await app.waitFor(by.contains('תקופת הניסיון הסתיימה ב-14 באוק'))).attr('name'));
  assert(date.includes('2026'), `дата окончания с годом 2026 (сейчас «${date}»)`);
  await app.scrollTo(by.contains('מכשירים מחוברים'), { max: 3, what: '«מכשירים מחוברים»' });
  assert(await app.exists(`(${by.contains('מכשירים מחוברים')}) AND (name CONTAINS "2 מתוך 2" OR label CONTAINS "2 מתוך 2")`), '«מכשירים מחוברים, 2 מתוך 2»');
  const pay = await app.scrollTo(by.begins('ניהול תשלום'), { max: 3, what: 'кнопка «ניהול תשלום»' });
  assert(!(await pay.enabled()), 'кнопка «ניהול תשלום» неактивна (disabled)');
  await app.scrollTo(by.contains('תשלום באפליקציה יתווסף בקרוב'), { max: 3, what: '«תשלום באפליקציה יתווסף בקרוב. עד אז הניטור וההתרעות ממשיכים לפעול כרגיל.»' });
  assert(await app.exists(by.contains('עד אז הניטור וההתרעות ממשיכים לפעול כרגיל')), 'текст «עד אז הניטור וההתרעות ממשיכים לפעול כרגיל.»');

  // Баг #a93d03: старых строк пробного периода нет (проверка после загрузки экрана, сверху до низа).
  for (const dir of ['up', 'down']) {
    await app.scrollTo(by.contains(dir === 'up' ? 'מנוי משפחתי' : 'תשלום באפליקציה יתווסף בקרוב'), { max: 3, direction: dir });
    for (const bad of ['מסתיימת ב-', 'בינתיים המנוי שלכם בתקופת ניסיון', 'תקופת ניסיון']) {
      assert(!(await app.exists(by.contains(bad))), `на экране «מנוי» нет «${bad}» (баг #a93d03)`);
    }
  }

  await app.restart();
}
